import{_ as r,o as s,c as t,O as n}from"./chunks/framework.2c2d5a61.js";const h=JSON.parse('{"title":"中间件（Redis & 消息队列）","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/06-中间件.md","filePath":"interview/后端/Java/06-中间件.md","lastUpdated":1789026500000}'),g={name:"interview/后端/Java/06-中间件.md"};function e(a,o,i,l,d,p){return s(),t("div",null,o[0]||(o[0]=[n('<h1 id="中间件-redis-消息队列" tabindex="-1">中间件（Redis &amp; 消息队列） <a class="header-anchor" href="#中间件-redis-消息队列" aria-label="Permalink to &quot;中间件（Redis &amp; 消息队列）&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-redis-为什么快-单线程模型-★★★" tabindex="-1">1. Redis 为什么快（单线程模型）★★★ <a class="header-anchor" href="#_1-redis-为什么快-单线程模型-★★★" aria-label="Permalink to &quot;1. Redis 为什么快（单线程模型）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 四件事：<strong>纯内存操作</strong>、<strong>单线程避免锁和线程切换</strong>、<strong>IO 多路复用</strong>（<strong>epoll</strong> 一个线程监听多连接）、<strong>数据结构高效</strong>。 注意「单线程」指的是<strong>命令执行是单线程</strong>，Redis 6.0 之后网络 IO 读写已经是多线程了。所以单个<strong>慢命令</strong>（<code>keys *</code>、删<strong>大 key</strong>）会卡住<strong>整个实例</strong>。</p><p><strong>我的项目关联</strong> Redis 在我们这儿是最基础的依赖：设备在线状态、订单、字典、<strong>分布式锁</strong>都靠它。因为它<strong>单线程</strong>，我们上线前特意排查过 <code>keys *</code> 这类命令，改成了 <code>scan</code>；删<strong>大 key</strong> 用 <code>unlink</code> 异步删，避免<strong>阻塞</strong>。</p><p><strong>面试答题话术</strong> 「Redis 快主要是<strong>内存</strong> + <strong>单线程无锁</strong> + <strong>IO 多路复用</strong>。单线程指的是<strong>命令执行</strong>，6.0 网络 IO 是多线程的。它最大的坑也是单线程——一个<strong>慢命令</strong>会<strong>阻塞</strong>整个实例，所以线上我们禁用 <code>keys</code>，删大 key 用 <code>unlink</code>。」</p><hr><h2 id="_2-redis-数据类型及底层结构-★★★" tabindex="-1">2. Redis 数据类型及底层结构 ★★★ <a class="header-anchor" href="#_2-redis-数据类型及底层结构-★★★" aria-label="Permalink to &quot;2. Redis 数据类型及底层结构 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> String（字符串/计数/位图）、Hash（对象）、List（列表/队列）、Set（去重）、<strong>ZSet</strong>（有序集合，排行榜）。 底层：ZSet 用<strong>跳表</strong>（查询 O(logn)、好做范围查询），小数据量时用 <strong>ziplist/listpack</strong> 省内存；String 用的是 <strong>SDS</strong>，有长度字段所以取长度为 O(1)、<strong>二进制安全</strong>。<strong>记结论就行，别抠跳表实现细节。</strong></p><p><strong>我的项目关联</strong> 选结构是体现功力的地方：设备最新状态用 <strong>Hash</strong>（一个设备一个 key，字段存电量/功率/状态）；排行榜、延迟任务用 <strong>ZSet</strong>；<strong>Bitmap</strong> 做设备在线/签到统计；<strong>HyperLogLog</strong> 做 <strong>UV 估算</strong>。</p><p><strong>面试答题话术</strong> 「常用的五种结构我都用过：<strong>Hash</strong> 存设备状态、<strong>ZSet</strong> 做延迟队列和排行、<strong>Bitmap</strong> 做在线统计。底层 ZSet 是<strong>跳表</strong>，查询 O(logn)，范围查询友好，比<strong>红黑树</strong>好实现。具体源码我不过深，知道结论够用了。」</p><hr><h2 id="_3-缓存穿透、击穿、雪崩-★★★-【简历亮点-高频追问】" tabindex="-1">3. 缓存穿透、击穿、雪崩 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_3-缓存穿透、击穿、雪崩-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;3. 缓存穿透、击穿、雪崩 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 三个长得像但原因完全不同的问题：</p><ul><li><strong>穿透</strong>：查一个根本不存在的数据，缓存和库都没有，每次都打库。解法：<strong>缓存空值</strong>（短过期）、<strong>布隆过滤器</strong>、参数校验。</li><li><strong>击穿</strong>：某个<strong>热点 key</strong> 刚好过期，瞬间大量请求一起打库。解法：<strong>互斥锁重建</strong>、热点 key 不设过期、<strong>逻辑过期</strong>。</li><li><strong>雪崩</strong>：大批 key 同时过期，或 Redis 整个挂了，请求全砸库。解法：过期时间加随机值、<strong>多级缓存</strong>、<strong>集群高可用</strong>、<strong>限流降级</strong>。</li></ul><p><strong>我的项目关联</strong><strong>真实经验</strong>：这类问题我们是靠「<strong>过期时间打散 + 空值缓存 + 限流</strong>」一起扛的。设备编号、订单号这类查询很适合被<strong>恶意扫</strong>，比如拿一堆不存在的桩编号来刷，我们就是靠<strong>缓存空值 + 网关限流</strong>拦的，属于<strong>线上处理过的</strong>场景。 <strong>布隆过滤器</strong>我在文档里研究过，也了解原理（多个哈希映射位数组，只会<strong>误判「存在」</strong>），但我们这块<strong>没实装，属于学习了解</strong>，面试别说是线上用的。</p><p><strong>面试答题话术</strong> 「三个问题我分开说：<strong>穿透</strong>是查不存在的数据，我用<strong>缓存空值加参数校验</strong>挡；<strong>击穿</strong>是热点 key 过期，我用<strong>互斥锁重建</strong>；<strong>雪崩</strong>是批量过期或 Redis 挂了，我把<strong>过期时间打散</strong>，加上<strong>限流降级</strong>兜底。<strong>布隆过滤器</strong>原理我清楚，但我们项目没用上，就不硬说用过了。」</p><hr><h2 id="_4-缓存与数据库一致性-★★★-【简历亮点-高频追问】" tabindex="-1">4. 缓存与数据库一致性 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_4-缓存与数据库一致性-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;4. 缓存与数据库一致性 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 最主流是 <strong>Cache Aside（旁路缓存）</strong>：读的时候先查缓存、没有再查库并回填；写的时候<strong>先更新数据库，再删除缓存</strong>。 为什么是「删缓存」不是「更新缓存」：删更简单，也避免<strong>并发写</strong>把<strong>旧值</strong>刷进缓存。为什么不是先删缓存：先删了缓存再更新库，中间有<strong>窗口</strong>会被别的请求读到旧数据又回填回去。 要做到<strong>最终一致</strong>可以加「<strong>延时双删</strong>」或订阅 <strong>binlog</strong>（<strong>Canal</strong>）异步删。<strong>缓存场景一般只承诺最终一致，做不到强一致。</strong></p><p><strong>我的项目关联</strong><strong>真实经验</strong>：订单、设备状态这类缓存，我们走的就是「先更库再删缓存」。支付<strong>对账</strong>场景里我们对<strong>一致性</strong>的要求比一般业务高，所以最敏感的对账数据是<strong>直接读库不走缓存</strong>的，缓存只用在允许<strong>短暂不一致</strong>的<strong>展示类数据</strong>上。这是<strong>业务取舍</strong>，不是纯技术选型。</p><p><strong>面试答题话术</strong> 「标准答案<strong>先更库再删缓存</strong>，因为删比更新简单、也不容易出错。但关键看业务：像<strong>对账</strong>、<strong>支付金额</strong>这种，我们宁可走库也不要缓存那点<strong>不一致窗口</strong>，缓存只用在展示类数据上。一致性上缓存只能做到<strong>最终一致</strong>，<strong>强一致</strong>就别用缓存。」</p><hr><h2 id="_5-redis-持久化-rdb-与-aof-★★★" tabindex="-1">5. Redis 持久化：RDB 与 AOF ★★★ <a class="header-anchor" href="#_5-redis-持久化-rdb-与-aof-★★★" aria-label="Permalink to &quot;5. Redis 持久化：RDB 与 AOF ★★★&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>RDB</strong>：定时把内存数据<strong>快照</strong>存盘（<strong>fork 子进程写，主进程照常服务</strong>）。文件小、恢复快，但两次快照之间的<strong>数据会丢</strong>。</li><li><strong>AOF</strong>：记录每条写命令追加到日志。<code>everysec</code> 是默认<strong>折中档</strong>（最多丢 1 秒）；<code>always</code> 最安全最慢；<code>no</code> 交给操作系统。文件大、恢复慢，靠 <strong>AOF 重写</strong>压缩。</li><li><strong>混合持久化</strong>（4.0+）：RDB 快照 + <strong>增量 AOF</strong>，恢复快又少丢数据。</li></ul><p><strong>我的项目关联</strong> 我们的 Redis 是当<strong>缓存和锁</strong>用的，<strong>核心数据都在 MySQL/Kafka 里，Redis 丢了可以重建</strong>，所以<strong>持久化</strong>不是我们的生命线。但如果被问「你线上怎么配」，我会说：缓存型实例可以只开 <strong>RDB</strong>，<strong>混合持久化</strong>是更稳的默认选择。</p><p><strong>面试答题话术</strong> 「RDB 是<strong>定时快照</strong>，恢复快、文件小但可能丢一段数据；AOF 记录每条写命令，<strong>everysec</strong> 最多丢一秒，但文件大恢复慢。生产一般用<strong>混合持久化</strong>。不过要说清：Redis 在我们项目里是缓存，真正<strong>不能丢的数据</strong>在 MySQL 和 Kafka，所以持久化对我们不是最关键的一环。」</p><hr><h2 id="_6-redis-过期删除策略与内存淘汰-★★★" tabindex="-1">6. Redis 过期删除策略与内存淘汰 ★★★ <a class="header-anchor" href="#_6-redis-过期删除策略与内存淘汰-★★★" aria-label="Permalink to &quot;6. Redis 过期删除策略与内存淘汰 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>过期删除</strong>：<strong>惰性删除</strong>（<strong>访问时才判断过期</strong>）+ <strong>定期删除</strong>（周期随机抽一批查），两者结合，平衡 CPU 和内存。</li><li><strong>内存淘汰</strong>（内存满时按 <code>maxmemory-policy</code>）：<code>noeviction</code> 不淘汰直接报错、<code>allkeys-lru</code> 淘汰最久未用、<code>volatile-lru</code> 只在设了过期时间的 key 里淘汰、<code>allkeys-lfu</code> 按访问频率淘汰。</li></ul><p><strong>我的项目关联</strong> 这个问题跟我上一题「Redis 内存满」是连着的。<strong>真实教训</strong>：没设 <code>maxmemory</code> 是<strong>最危险的</strong>，Redis 会一直吃内存直到被系统的 <strong>OOM Killer</strong> 干掉。我们后来是<strong>显式设置</strong> <code>maxmemory</code> + <code>allkeys-lru</code>。</p><p><strong>面试答题话术</strong> 「过期删除是<strong>惰性加定期</strong>结合。<strong>淘汰策略</strong>我一般配 <code>allkeys-lru</code>。这里有个<strong>坑</strong>：不设 <code>maxmemory</code>，Redis 会把系统内存<strong>吃光然后被杀掉</strong>，我们踩过这个方向的风险，所以一定要显式设上限。」</p><hr><h2 id="_7-redis-分布式锁-redisson-★★★-【简历亮点-高频追问】" tabindex="-1">7. Redis 分布式锁（Redisson）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-redis-分布式锁-redisson-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. Redis 分布式锁（Redisson）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 最基础写法是 <code>SET key value NX EX 秒</code>，value 放<strong>唯一标识</strong>（UUID + 线程 id），<strong>释放时先校验 value 再删</strong>，防止<strong>删错别人的锁</strong>。 几个必须知道的点：</p><ul><li><strong>释放锁要用 Lua</strong>：把「判断 + 删除」做成<strong>原子操作</strong>。</li><li><strong>锁续期</strong>：业务没跑完锁就过期了 → Redisson 的<strong>看门狗</strong>（Watch Dog）<strong>自动续期</strong>。</li><li><strong>可重入</strong>：Redisson 支持。</li><li><strong>主从丢锁</strong>：主节点宕机、锁还没同步到从节点就丢了 → 用 <strong>RedLock</strong> 缓解，但 RedLock 本身<strong>有争议</strong>。</li></ul><p><strong>我的项目关联</strong><strong>这是真实在用的</strong>。充电场景对「同一把枪不能同时下两条启动指令」很敏感，我们就是用 Redisson 加锁保证同一把枪/同一个订单<strong>串行处理</strong>；<strong>对账任务</strong>也用它防止多个实例<strong>重复跑</strong>。<strong>真实踩过的坑</strong>：早期写业务时没注意<strong>锁的释放</strong>要在 finally 里，且要判<strong>当前线程持有</strong>，后来统一改用 Redisson 的 <code>tryLock</code> + <strong>看门狗</strong>，才把「业务没跑完锁过期」的问题解决掉。</p><p><strong>面试答题话术</strong> 「分布式锁我用的是 Redisson。基础是 SET NX EX 加 Lua 释放，Redisson 额外解决了<strong>看门狗续期</strong>和<strong>可重入</strong>。项目里用来保证同一把充电枪、同一个订单不会并发出问题。要说坑就是——<strong>锁的过期时间</strong>要跟<strong>业务耗时匹配</strong>，不然业务没跑完锁就没了，这个我们用看门狗兜的。」</p><hr><h2 id="_8-redis-集群-主从、哨兵、cluster-★★★" tabindex="-1">8. Redis 集群：主从、哨兵、Cluster ★★★ <a class="header-anchor" href="#_8-redis-集群-主从、哨兵、cluster-★★★" aria-label="Permalink to &quot;8. Redis 集群：主从、哨兵、Cluster ★★★&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>主从复制</strong>：主写从读，做备份和<strong>读写分离</strong>。</li><li><strong>哨兵（Sentinel）</strong>：监控主从，<strong>主挂了自动选举新主</strong>，解决<strong>高可用</strong>。</li><li><strong>Cluster</strong>：数据分片到 <strong>16384 个槽</strong>，多主水平扩展，解决<strong>容量和扩展性</strong>，自带<strong>故障转移</strong>。 一句话区分：哨兵解决「一个主的高可用」，集群解决「要多主扩展」。</li></ul><p><strong>我的项目关联</strong> 我们用的是<strong>主从 + 哨兵</strong>，数据量还没到需要 <strong>Cluster 分片</strong>的程度。涉及分布式锁时要注意<strong>主从切换期间的丢锁窗口</strong>（见上一题）。</p><p><strong>面试答题话术</strong> 「主从做<strong>读写分离</strong>和备份，哨兵做<strong>故障转移</strong>保证<strong>高可用</strong>，Cluster 做<strong>分片扩展</strong>。我们现在是主从加哨兵就够了，没到要 Cluster 的量级。要注意主从切换时分布式锁可能丢，这是个<strong>经典问题</strong>。」</p><hr><h2 id="_9-缓存预热、缓存降级、热点-key-★★☆" tabindex="-1">9. 缓存预热、缓存降级、热点 key ★★☆ <a class="header-anchor" href="#_9-缓存预热、缓存降级、热点-key-★★☆" aria-label="Permalink to &quot;9. 缓存预热、缓存降级、热点 key ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>缓存预热</strong>：启动时提前把热点数据加载进缓存，避免<strong>冷启动打库</strong>。<strong>缓存降级</strong>：缓存/库压力大时返回<strong>兜底数据</strong>或直接限流。<strong>热点 key</strong>：访问过度集中，可以做<strong>本地缓存 + Redis 二级缓存分流</strong>。</p><p><strong>我的项目关联</strong> 后台的字典、配置类数据我们是<strong>启动预热 + 本地缓存</strong>扛的，量不大但<strong>查询频繁</strong>。热点 key 目前没到需要专门<strong>分片</strong>的程度。</p><p><strong>面试答题话术</strong> 「<strong>预热</strong>就是启动时先把热点数据放缓存，<strong>降级</strong>是扛不住时返回<strong>兜底数据</strong>，热点 key 用<strong>本地缓存加 Redis 两级分流</strong>。了解这些思路就行，我们实际主要用了预热。」</p><hr><h2 id="_10-为什么用消息队列-★★★" tabindex="-1">10. 为什么用消息队列 ★★★ <a class="header-anchor" href="#_10-为什么用消息队列-★★★" aria-label="Permalink to &quot;10. 为什么用消息队列 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 三大作用：<strong>解耦</strong>（生产消费不直接依赖）、<strong>异步</strong>（非核心流程异步跑，接口更快返回）、<strong>削峰</strong>（高峰入队，消费者按自己的节奏消费，保护下游）。 代价是：系统变复杂、有<strong>消息丢失/重复</strong>的<strong>一致性问题</strong>、<strong>强依赖 MQ 的可用性</strong>。</p><p><strong>我的项目关联</strong><strong>这就是我们 Kafka 的定位</strong>。充电桩上报的<strong>实时数据</strong>、<strong>订单状态变更</strong>、<strong>支付回调后的异步处理</strong>都是走 Kafka。核心价值是<strong>削峰</strong>：大量设备同时上报，不可能同步一条条写库；先丢进 Kafka，消费者按能力消费，把<strong>数据库压力抹平</strong>。</p><p><strong>面试答题话术</strong> 「我们用 MQ 主要是削峰和解耦。设备上报、订单状态变更量很大而且有<strong>突发</strong>，同步处理会<strong>把库打爆</strong>，所以先进 Kafka 异步消费。代价是引入了<strong>消息丢失和重复</strong>的问题，所以消费端必须做<strong>幂等</strong>。」</p><hr><h2 id="_11-消息丢失怎么解决-★★★-【简历亮点-高频追问】" tabindex="-1">11. 消息丢失怎么解决 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_11-消息丢失怎么解决-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;11. 消息丢失怎么解决 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 分三个环节堵：</p><ol><li><strong>生产者丢</strong>：发的时候网络挂了 → 用<strong>发送确认（ack）</strong>/ <strong>重试</strong> / <strong>事务消息</strong>。</li><li><strong>MQ 自己丢</strong>：没持久化就宕机 → 开<strong>持久化 + 多副本</strong>（主从）。</li><li><strong>消费者丢</strong>：消息收到还没处理完就挂 → 关掉<strong>自动提交</strong>，改成<strong>处理完手动 ack</strong>。</li></ol><p><strong>我的项目关联</strong><strong>真实经验</strong>：这套「<strong>生产确认 + broker 持久化多副本 + 消费手动提交</strong>」是我们的标配。<strong>对账场景</strong>最怕丢消息，所以消费端一律手动提交，处理成功才<strong>提交位移</strong>。<strong>这是线上一直在用的方案</strong>。</p><p><strong>面试答题话术</strong> 「消息丢失分三段防：生产者用发送确认加重试，broker 开持久化和多副本，消费者关自动提交、处理完手动 ack。核心是保证『<strong>至少一次</strong>』投递。我们在<strong>支付、对账</strong>这类消息上就是手动提交，<strong>宁可重复也不能丢</strong>。」</p><hr><h2 id="_12-消息重复消费怎么解决-★★★-【简历亮点-高频追问】" tabindex="-1">12. 消息重复消费怎么解决 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_12-消息重复消费怎么解决-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;12. 消息重复消费怎么解决 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 因为保证「<strong>至少一次</strong>」投递，加上网络重试，重复是<strong>天然的、避不开的</strong>。<strong>MQ 本身保证不了不重复，只能靠消费端做幂等。</strong> 常用幂等手段：数据库<strong>唯一索引</strong>（插入冲突就忽略）、Redis <code>setnx</code> 记录处理过的<strong>消息 id</strong>、<strong>状态机</strong>（订单已支付就跳过）。</p><p><strong>我的项目关联</strong><strong>真实经验</strong>：充电订单的状态流转就是典型的<strong>状态机</strong> —— 一条「充电结束」的消息<strong>重复消费</strong>，第二次会被状态判断挡掉。<strong>支付回调</strong>同理，用<strong>唯一索引 + 状态判断</strong>防<strong>重复扣款</strong>。这是我们<strong>线上真在用</strong>的设计，也是面试最容易被追问的点。</p><p><strong>面试答题话术</strong> 「至少一次投递必然可能重复，所以<strong>幂等</strong>只能消费端做。我们的做法是：订单走<strong>状态机</strong>，已经结束的订单再收到消息直接跳过；支付相关用<strong>唯一索引</strong>兜底。原则就是——<strong>不假设消息只来一次</strong>。」</p><hr><h2 id="_13-消息顺序消费-★★☆" tabindex="-1">13. 消息顺序消费 ★★☆ <a class="header-anchor" href="#_13-消息顺序消费-★★☆" aria-label="Permalink to &quot;13. 消息顺序消费 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 要顺序就两点：同一业务的消息发到<strong>同一个分区/队列</strong>，消费者<strong>单线程</strong>消费。Kafka 只保证<strong>分区内有序</strong>。 <strong>全局有序</strong>只能用一个队列 + 单消费者，<strong>性能很差</strong>，一般没必要。</p><p><strong>我的项目关联</strong> 我们只需要保证「<strong>同一个订单/同一把枪</strong>」的消息有序，不是<strong>全局有序</strong>，所以<strong>按 key 哈希到同一分区</strong>就够了。</p><p><strong>面试答题话术</strong> 「顺序只在同一个<strong>分区内</strong>保证，做法是<strong>按业务 key 哈希到同一分区、单线程消费</strong>。<strong>全局有序性能太差</strong>，一般只要同一订单内有序就够了。」</p><hr><h2 id="_14-消息积压怎么解决-★★☆" tabindex="-1">14. 消息积压怎么解决 ★★☆ <a class="header-anchor" href="#_14-消息积压怎么解决-★★☆" aria-label="Permalink to &quot;14. 消息积压怎么解决 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 方向就三个：<strong>加消费者/提并发</strong>、<strong>优化消费逻辑</strong>（批处理、减少 IO）、<strong>临时分流到新 topic</strong>。前提是先看<strong>消费者是不是卡住了</strong>。</p><p><strong>我的项目关联</strong><strong>通用坑</strong>。我们目前量级没出现<strong>严重积压</strong>，但监控里是会对<strong>消费延迟告警</strong>的。</p><p><strong>面试答题话术</strong> 「积压先查是不是<strong>消费卡了</strong>，然后加消费者、<strong>提并发</strong>、优化消费逻辑、必要时开新 topic 分流。核心是<strong>先定位瓶颈再扩容</strong>。」</p><hr><h2 id="_15-死信队列、延迟消息-★★☆" tabindex="-1">15. 死信队列、延迟消息 ★★☆ <a class="header-anchor" href="#_15-死信队列、延迟消息-★★☆" aria-label="Permalink to &quot;15. 死信队列、延迟消息 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>死信队列</strong>：消息重试到上限、过期了、队列满了，会进死信队列，用来<strong>人工排查和告警</strong>。<strong>延迟消息</strong>：消息延迟一段时间才投递，<strong>RocketMQ 原生支持</strong>，RabbitMQ 用 <strong>TTL + 死信模拟</strong>，Kafka 要自己实现。</p><p><strong>我的项目关联</strong><strong>限时订单的超时取消</strong>就跟这个相关 —— 不过我们<strong>不是靠 MQ 延迟消息</strong>，而是延迟消息 + <strong>定时任务兜底</strong>（08 笔记里详细讲了）。</p><p><strong>面试答题话术</strong> 「死信队列存<strong>重试失败或过期</strong>的消息，用来告警和<strong>人工补偿</strong>。延迟消息可以拿来做<strong>订单超时取消</strong>，但只靠延迟消息不够稳，得有<strong>定时任务兜底</strong>。」</p><hr><h2 id="_16-kafka、rocketmq、rabbitmq-对比-★★☆" tabindex="-1">16. Kafka、RocketMQ、RabbitMQ 对比 ★★☆ <a class="header-anchor" href="#_16-kafka、rocketmq、rabbitmq-对比-★★☆" aria-label="Permalink to &quot;16. Kafka、RocketMQ、RabbitMQ 对比 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>Kafka</strong>：大数据/日志/<strong>高吞吐</strong>场景，<strong>性能最强</strong>，事务和延迟消息相对弱。</li><li><strong>RocketMQ</strong>：业务消息，支持<strong>事务消息</strong>、<strong>原生延迟消息</strong>，Java 生态。</li><li><strong>RabbitMQ</strong>：通用、<strong>协议标准（AMQP）</strong>，吞吐中等。</li></ul><p><strong>我的项目关联</strong> 我们选 Kafka 是因为设备上报<strong>数据量大</strong>、<strong>吞吐要求高</strong>，对<strong>事务消息和延迟消息</strong>没强需求（超时用定时任务兜底）。</p><p><strong>面试答题话术</strong> 「Kafka <strong>吞吐最高</strong>，适合数据量大、日志/流场景；RocketMQ <strong>业务消息能力强</strong>，有事务消息和延迟消息；RabbitMQ 通用、<strong>生态成熟</strong>。我们选 Kafka 就是冲吞吐，业务上的超时兜底用定时任务解决。」</p><hr><h2 id="_17-缓存设计模式-★★★" tabindex="-1">17. 缓存设计模式 ★★★ <a class="header-anchor" href="#_17-缓存设计模式-★★★" aria-label="Permalink to &quot;17. 缓存设计模式 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>Cache Aside</strong>（最常用）：读先查缓存、<strong>未命中查库回填</strong>；写先更库再删缓存。</li><li><strong>Read Through</strong>：查库回填的逻辑<strong>封装在缓存组件里</strong>，应用不感知数据库。</li><li><strong>Write Through</strong>：写的时候缓存和库<strong>同步更新</strong>，一致性好但<strong>写开销大</strong>。</li><li><strong>Write Behind</strong>：只写缓存，<strong>异步批量刷库</strong>，<strong>性能最高但最可能丢数据</strong>。</li></ul><p><strong>我的项目关联</strong> 我们实际就一种：<strong>Cache Aside</strong>。其余三种属于<strong>了解概念</strong>，面试提一下区别就够。</p><p><strong>面试答题话术</strong> 「我们用的是<strong>旁路缓存 Cache Aside</strong>，<strong>读回填、写删缓存</strong>。Write Through 和 Write Behind 属于了解——前者<strong>同步写库</strong>一致性好但慢，后者<strong>异步批量写</strong>快但可能丢数据，一般业务不会选。」</p><hr><h2 id="_18-redis-pipeline-的好处-★★☆" tabindex="-1">18. Redis Pipeline 的好处 ★★☆ <a class="header-anchor" href="#_18-redis-pipeline-的好处-★★☆" aria-label="Permalink to &quot;18. Redis Pipeline 的好处 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 把多条命令<strong>打包一次发过去</strong>，把 N 次**网络往返（RTT）**变成 1 次。 注意：<strong>Pipeline 不是原子操作</strong>，<strong>命令之间可能被别的客户端插进来</strong>；要原子得配事务 <code>MULTI/EXEC</code>。</p><p><strong>我的项目关联</strong><strong>批量查设备状态</strong>时用过，就是减少<strong>网络往返</strong>。我们没做原生化，属于<strong>常规优化</strong>。</p><p><strong>面试答题话术</strong> 「Pipeline 就是把多条命令<strong>打包发</strong>，省<strong>网络往返时间</strong>。要注意它不是<strong>原子的</strong>，要原子得配事务。适合<strong>批量写、批量查</strong>的场景。」</p><hr><h2 id="_19-redis-和-hashmap-的区别-★★☆" tabindex="-1">19. Redis 和 HashMap 的区别 ★★☆ <a class="header-anchor" href="#_19-redis-和-hashmap-的区别-★★☆" aria-label="Permalink to &quot;19. Redis 和 HashMap 的区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> Redis 是独立部署的<strong>分布式缓存服务</strong>，走网络，能<strong>跨进程跨机器共享</strong>、有<strong>持久化和过期</strong>。HashMap 是 JVM 里的<strong>本地数据结构</strong>，单机单进程，重启就没了，也不共享。</p><p><strong>我的项目关联</strong> 认知层面的东西。<strong>多实例部署</strong>的服务必须用 Redis <strong>共享数据</strong>，本地 HashMap 只能放配置类<strong>只读数据</strong>。这个点跟 04 笔记里「单例 Bean 里放 HashMap 当缓存翻车」是同一个道理。</p><p><strong>面试答题话术</strong> 「本质区别是 Redis 是<strong>独立服务</strong>、能跨机器共享还有<strong>持久化</strong>；HashMap 是 JVM 内的，<strong>多实例之间不共享</strong>。我们<strong>多副本部署</strong>，所以共享数据必须走 Redis，本地 Map 只能放只读配置。」</p><hr><h2 id="_20-redis、本地缓存-caffeine-、memcached-怎么选-★★☆" tabindex="-1">20. Redis、本地缓存（Caffeine）、Memcached 怎么选 ★★☆ <a class="header-anchor" href="#_20-redis、本地缓存-caffeine-、memcached-怎么选-★★☆" aria-label="Permalink to &quot;20. Redis、本地缓存（Caffeine）、Memcached 怎么选 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li>需要<strong>跨服务共享</strong>、要<strong>持久化</strong>、要<strong>丰富数据结构</strong> → Redis。</li><li>单机内热点数据、要<strong>纳秒级低延迟</strong>、不用共享（配置、字典）→ 本地缓存。</li><li>常见组合：本地缓存做一层，Redis 做二层，<strong>减少网络开销</strong>。</li><li>Memcached 只有简单 KV、无持久化，现在基本<strong>被 Redis 取代</strong>。</li></ul><p><strong>我的项目关联</strong> 字典、协议参数这类<strong>只读数据</strong>我们走本地缓存；需要<strong>跨实例一致</strong>的走 Redis。<strong>两级缓存的一致性问题</strong>要留意。</p><p><strong>面试答题话术</strong> 「共享数据用 Redis，<strong>单机热点和只读字典</strong>用本地缓存，两者可以组合成<strong>两级</strong>。Memcached 现在基本<strong>被 Redis 替代</strong>了。」</p><hr><h2 id="_21-redis-内存用完了会发生什么-★★★-【简历亮点-高频追问】" tabindex="-1">21. Redis 内存用完了会发生什么 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_21-redis-内存用完了会发生什么-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;21. Redis 内存用完了会发生什么 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 看<strong>淘汰策略</strong>：默认 <code>noeviction</code> 的话，内存满了<strong>写命令直接报错</strong>，读还能用；配了 <code>allkeys-lru</code> 之类就会<strong>淘汰旧 key 继续写</strong>。 最危险的是<strong>没配 <code>maxmemory</code></strong> —— Redis 会一直吃内存直到<strong>被系统 OOM Killer 杀掉</strong>。</p><p><strong>我的项目关联</strong><strong>真实关注点</strong>：容器里跑的服务最怕被 <strong>OOM Killer 干掉</strong>（02 笔记里 JVM 也讲过这个）。Redis 同理，我们一定会<strong>显式配</strong> <code>maxmemory</code>，不让它把<strong>宿主机内存吃光</strong>。</p><p><strong>面试答题话术</strong> 「内存满的行为由<strong>淘汰策略决定</strong>：noeviction 写报错、lru 就淘汰旧数据。<strong>真正的坑</strong>是不设 maxmemory，Redis 会把机器内存吃光然后被系统杀掉。所以我们线上一定<strong>显式设上限和策略</strong>。」</p><hr><h2 id="_22-mq-部署单机还是集群、高可用怎么保证-★★★" tabindex="-1">22. MQ 部署单机还是集群、高可用怎么保证 ★★★ <a class="header-anchor" href="#_22-mq-部署单机还是集群、高可用怎么保证-★★★" aria-label="Permalink to &quot;22. MQ 部署单机还是集群、高可用怎么保证 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 生产必须集群。Kafka 靠 partition <strong>多副本</strong>（leader + follower）<strong>自动选主</strong>；RocketMQ 靠主从 + <strong>NameServer 集群</strong>；RabbitMQ 用<strong>镜像队列或 Quorum Queue</strong>。</p><p><strong>我的项目关联</strong> 我们 Kafka 是多副本部署的。<strong>真实踩过的方向</strong>：<strong>单副本</strong>时 broker 一挂消息就丢，必须把<strong>副本数设够</strong>、且 <code>acks</code> <strong>配置到位</strong>，这是<strong>上线前要确认</strong>的。</p><p><strong>面试答题话术</strong> 「生产必须集群。Kafka 是<strong>多副本加自动选主</strong>，<strong>副本数和 acks 配置要配对</strong>，不然后面数据丢了都发现不了。我们<strong>上线前专门确认过</strong>这两个配置。」</p><hr><h2 id="_23-消息队列的延时、过期失效问题-★★★" tabindex="-1">23. 消息队列的延时、过期失效问题 ★★★ <a class="header-anchor" href="#_23-消息队列的延时、过期失效问题-★★★" aria-label="Permalink to &quot;23. 消息队列的延时、过期失效问题 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>消息设了 TTL</strong> 又一直没人消费，<strong>过期进死信</strong>，导致<strong>该处理的业务没处理</strong>。 解法：<strong>死信队列兜底做补偿/告警</strong>、<strong>监控积压及时扩容</strong>、别设过短 TTL。</p><p><strong>我的项目关联</strong><strong>通用坑</strong>。我们的做法是<strong>不依赖 MQ 的 TTL 做兜底</strong>，关键业务用<strong>定时任务扫表补偿</strong>，避免「消息过期了业务就静默丢了」。</p><p><strong>面试答题话术</strong> 「消息过期失效的本质是<strong>该处理的业务静默丢了</strong>。解法是<strong>死信队列兜底加监控告警</strong>，更重要的是关键业务<strong>别只依赖 MQ</strong>，要用<strong>定时任务兜底</strong>。」</p><hr><h2 id="_24-如果让你写一个消息队列-如何架构-★★★" tabindex="-1">24. 如果让你写一个消息队列，如何架构 ★★★ <a class="header-anchor" href="#_24-如果让你写一个消息队列-如何架构-★★★" aria-label="Permalink to &quot;24. 如果让你写一个消息队列，如何架构 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 设计题，讲清模块就行：存储（<strong>顺序写日志</strong>）、分区（并行 + 局部顺序）、网络通信（高性能框架如 Netty）、<strong>投递与位移管理</strong>、<strong>多副本高可用</strong>、<strong>可靠投递</strong>（ack + 重试）。 亮点：<strong>顺序写 + 页缓存 + 零拷贝</strong>提升吞吐。</p><p><strong>我的项目关联</strong><strong>这个题我有个天然优势</strong> —— 我在 T-CEC 互联互通网关里就是用 Netty 做<strong>长连接接入</strong>的，对「<strong>高性能网络 + 协议编解码 + 连接管理</strong>」是<strong>真实经验</strong>。虽然没写过 MQ，但网络层这块能讲得很实。</p><p><strong>面试答题话术</strong> 「它的核心模块是：<strong>顺序写日志做存储</strong>、分区做并行、Netty 做网络层、offset 管进度、<strong>多副本做高可用</strong>。Kafka 快的关键是<strong>顺序写加页缓存加零拷贝</strong>。网络这块我有实际经验——我们的协议网关就是 Netty 做的<strong>长连接接入</strong>，所以高并发连接处理我比较有体感。」</p><hr><h2 id="_25-redis-慢查询怎么找、怎么优化-★★★-【简历亮点-高频追问】" tabindex="-1">25. Redis 慢查询怎么找、怎么优化 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_25-redis-慢查询怎么找、怎么优化-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;25. Redis 慢查询怎么找、怎么优化 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 找：配 <code>slowlog-log-slower-than</code> <strong>阈值</strong>，用 <code>slowlog get</code> 看<strong>慢命令</strong>，也可以用 <code>latency monitor</code>。 优化：禁用 <code>keys *</code> 改 <code>scan</code>、拆<strong>大 key</strong>、异步 <code>unlink</code> 删大 key、用 <strong>pipeline</strong>、调<strong>持久化策略</strong>。</p><p><strong>我的项目关联</strong><strong>真实排查过</strong>。现象是<strong>接口偶发变慢</strong>，查下来是某个<strong>大 key 操作阻塞了单线程</strong>。定位手段就是 <code>slowlog</code>，修复是<strong>拆 key</strong> + 改 <code>unlink</code>，之后就没再出现。<strong>这条是线上真实排查过的。</strong></p><p><strong>面试答题话术</strong> 「Redis 慢的根因是<strong>单线程</strong>，一个<strong>慢命令会卡住后面所有请求</strong>。定位靠 slowlog。我们真遇到过一次，接口<strong>偶发变慢</strong>，slowlog 里看到是在<strong>操作大 key</strong>，拆了 key、删除改成 unlink 就好了。」</p><hr><h2 id="_26-redis-性能优化-★★★" tabindex="-1">26. Redis 性能优化 ★★★ <a class="header-anchor" href="#_26-redis-性能优化-★★★" aria-label="Permalink to &quot;26. Redis 性能优化 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 按层看：内存（<strong>淘汰策略</strong>、<strong>控制大 key</strong>）、命令（避开 O(n)、用 scan/pipeline）、网络（pipeline、6.0 多线程 IO）、持久化（AOF everysec + <strong>及时重写</strong>）、架构（主从读写分离、Cluster 分片、<strong>热点 key 本地缓存</strong>）、参数（maxmemory、连接池）。</p><p><strong>我的项目关联</strong> 我们实际做的主要是：<strong>控制大 key</strong>、<strong>连接池调优</strong>、<strong>热点数据本地缓存</strong>。Cluster 暂时没上。</p><p><strong>面试答题话术</strong> 「优化我分几层说：命令层<strong>避开慢命令和大 key</strong>，网络层用 pipeline，架构层<strong>主从读写分离加热点本地缓存</strong>，参数层设好 maxmemory 和连接池。我们主要做的是<strong>大 key 控制和连接池调优</strong>。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>Redis 事务（MULTI/EXEC）</strong>：多条命令打包执行，但<strong>不支持回滚</strong>，<strong>某条失败其余照常执行</strong>，所以基本没人拿它当事务用。</li><li><strong>Redis 发布订阅</strong>：能广播但<strong>消息不持久化、不可靠</strong>，业务里一般用 Kafka 代替。</li><li><strong>Memcached</strong>：纯内存 KV、多线程、无持久化，现在基本被 Redis 取代，了解概念即可。</li></ul>',144)]))}const k=r(g,[["render",e]]);export{h as __pageData,k as default};
